"use strict";

window.addEventListener('DOMContentLoaded', function () {
  $('.js-download-form').each(function () {
    var $form = $(this); // 期間選択selectbox

    var $term = $form.find('select[name="period"]'); // エラーメッセージ

    var $error = $form.find('.js-download-form--error');
    $form.on('submit', function () {
      var val = $term.val(); // console.log(val);

      if (val) {
        $error.text('.');
        $error.removeClass('has-error');
      } else {
        $error.text('Please select a month');
        $error.addClass('has-error');
        return false;
      }
    });
  });
});